async function openTodoTarget(todo){
  const stayInWorkbench=state.page==='overview';
  if(['candidate','source','brief','draft'].includes(todo.kind)){
    state.scriptStage=todo.stage||'all';
    if(!stayInWorkbench&&!await navigate('scripts'))return;
    if(todo.kind==='candidate'&&!state.sourceCandidates)state.sourceCandidates=await api('/api/source-candidates');
    const collection=todo.kind==='candidate'?(state.sourceCandidates?.candidates||[]):todo.kind==='source'?(state.scripts?.sources||[]):todo.kind==='brief'?(state.scripts?.briefs||[]):(state.scripts?.drafts||[]);
    const key={candidate:'candidate_id',source:'source_id',brief:'brief_id',draft:'draft_id'}[todo.kind];
    const item=collection.find(row=>row[key]===todo.id);
    if(!item)return missingTodoTarget();
    if(todo.kind==='candidate')return openSourceCandidateDrawer(item);
    if(todo.kind==='source')return openSourceDrawer(item);
    if(todo.kind==='brief')return openBriefDrawer(item);
    return openDraftDrawer(item);
  }
  if(['production_setup','master_review','provider_action','final_acceptance'].includes(todo.kind)){
    state.videoFilter=todo.stage||'all';
    if(!stayInWorkbench&&!await navigate('videos'))return;
    const item=state.videos?.jobs.find(job=>job.job_id===todo.id);
    return item?openVideoDrawer(item):missingTodoTarget();
  }
  if(todo.kind==='publish'){
    if(!stayInWorkbench&&!await navigate('publishing'))return;
    const item=state.publishing?.ready.find(row=>row.job_id===todo.id);
    return item?openPublishFlow(item):missingTodoTarget();
  }
  if(todo.kind==='performance'){
    if(!stayInWorkbench&&!await navigate('publishing'))return;
    const item=state.publishing?.publications.find(row=>row.publication_id===todo.id);
    return item?openPublicationDrawer(item):missingTodoTarget();
  }
  missingTodoTarget();
}

