function renderStudioStage(project,r){const body=$('#studio-stage-body');if(state.studioStage==='source'){body.innerHTML=`<div class="studio-stage-grid single">${studioTextPanel('SOURCE MATERIAL',r.source?.title||'未命名来源',r.source?.content||'暂无正文',`${sourceTypeLabel(r.source?.source_type)} · ${r.source?.source_display||'人工创建'} · ${r.source?.created_at||''}`)}<aside class="studio-note"><b>输入质量</b><strong>${project.quality_gate.score}</strong><p>${esc(project.quality_gate.reason)}</p><button class="mini-action" id="studio-open-source">查看来源详情</button></aside></div>`;$('#studio-open-source').onclick=()=>openSourceDrawer(r.source);return}if(state.studioStage==='brief'){const brief=r.brief?.brief||{};const angles=brief.angles||[];body.innerHTML=`<div class="studio-brief-board"><header><div><p class="section-no">TOPIC DECISION</p><h3>${esc(r.brief?.recommended_title||'选题简报')}</h3><p>${esc(brief.audience||'暂无目标人群')}</p></div><span class="studio-score">${Number(brief.source_score?.overall||0).toFixed(0)}<small>综合分</small></span></header><div class="studio-angle-grid">${angles.map((angle,index)=>`<article class="studio-angle ${index===Number(brief.recommended_index||0)?'recommended':''}"><b>0${index+1}</b><h4>${esc(angle.title)}</h4><p>${esc(angle.hook)}</p><small>${esc(angle.promise)}</small></article>`).join('')}</div><button class="mini-action" id="studio-open-brief">查看完整选题策略</button></div>`;$('#studio-open-brief').onclick=()=>openBriefDrawer(r.brief);return}if(state.studioStage==='script'){const selected=r.selected||r.drafts[0];const script=selected?.script||{};body.innerHTML=`<div class="studio-script-workspace"><aside class="studio-variant-list">${r.drafts.map(item=>`<button class="${item.draft_id===selected?.draft_id?'active':''}" data-studio-draft="${esc(item.draft_id)}"><b>版本 ${Number(item.variant_index)+1}</b><span>${esc(scriptStatus(item.status))}</span><small>${esc(item.script?.title||'未命名剧本')}</small></button>`).join('')}</aside><article class="studio-script-sheet"><header><div><p class="section-no">SCRIPT SHEET</p><h3>${esc(script.title||'剧本')}</h3></div><span>${Number(script.total_duration_sec||script.target_duration_sec||0)} 秒</span></header><div class="studio-beats">${(script.beats||[]).map((beat,index)=>`<article><b>${String(index+1).padStart(2,'0')}</b><span><small>${esc(beat.speaker)} · ${esc(beat.beat)}</small><p>${esc(beat.dialogue)}</p><em>${esc(beat.visual_intent||'')}</em></span><i>${Number(beat.duration_sec||0)}s</i></article>`).join('')}</div></article></div>`;$$('[data-studio-draft]').forEach(button=>button.onclick=()=>openDraftDrawer(r.drafts.find(item=>item.draft_id===button.dataset.studioDraft)));return}if(state.studioStage==='video'){const video=r.video;if(!video){body.innerHTML='<div class="studio-empty"><b>尚未创建视频任务</b><span>审核剧本后即可进入制作设置</span></div>';return}const masterCount=video.master_count||video.planned_masters?.length||0;body.innerHTML=`<div class="studio-video-workspace"><aside class="studio-shot-list">${(video.planned_masters||[]).map((shot,index)=>`<article class="${index===0?'active':''}"><b>0${shot.idx||index+1}</b><span><strong>${esc(shot.speaker||shot.type||'镜头')}</strong><small>${esc(shot.shot_type||shot.render_mode||'母片')}</small></span><i>${Number(shot.duration||shot.duration_sec||0)}s</i></article>`).join('')||'<p class="empty-inline">尚未规划母片</p>'}</aside><div class="studio-video-viewer">${video.final_exists?`<video controls preload="metadata" src="${videoFileUrl(video)}"></video>`:`<div class="studio-empty"><b>${esc(video.display_state_label||videoStateLabel(video.display_state||video.state))}</b><span>${video.completed_master_count||0} / ${masterCount} 条母片完成</span></div>`}<footer><span><b>${esc(videoStateLabel(video.display_state||video.state))}</b><small>${video.completed_master_count||0}/${masterCount} 母片 · ${money(video.cost_cents)}</small></span><button class="mini-action" id="studio-open-video">打开制作检查器</button></footer></div></div>`;$('#studio-open-video').onclick=()=>openVideoDrawer(video);return}const rows=r.publications;body.innerHTML=`<div class="studio-publish-workspace"><header><div><p class="section-no">DISTRIBUTION</p><h3>发布与绩效</h3><p>${rows.length?'已登记的平台作品和绩效快照':'成片通过验收后，选择渠道并登记发布结果'}</p></div><button class="primary-action" id="studio-publish-action">${rows.length?'继续管理发布':'进入发布流程'}</button></header><div class="studio-channel-grid">${['douyin','weixin_channels'].map(platform=>{const row=rows.find(item=>item.platform===platform);return `<article class="${row?'ready':''}"><span class="platform-logo ${platform}">${platformName(platform)[0]}</span><div><b>${platformName(platform)}</b><small>${row?`作品 ${row.item_id}`:'尚未登记'}</small></div><i>${row?'✓':'—'}</i></article>`}).join('')}</div></div>`;$('#studio-publish-action').onclick=()=>routeProjectAction(project)}
