  $('#studio-inspector-body').innerHTML=`<section class="studio-inspector-section"><p class="section-no">NEXT ACTION</p><h4>${esc(next)}</h4><p>${esc(q.suggestion||'按当前阶段继续处理')}</p><button class="primary-action" id="studio-inspector-next">${esc(next)}</button></section><section class="studio-inspector-section"><header><b>质量检查</b><span>${q.score} / 100</span></header><div class="studio-quality-bar"><i style="width:${Math.max(0,Math.min(100,q.score))}%"></i></div><p>${esc(q.reason)}</p></section><section class="studio-inspector-section"><b>项目上下文</b>${detailRow('来源',sourceTypeLabel(project.source.source_type))}${detailRow('剧本',r.selected?.script?.title||'尚未选择')}${detailRow('人物',people.join('、')||'AI 按剧本生成')}${detailRow('视频成本',video?money(video.cost_cents):'尚未发生')}${detailRow('发布渠道',r.publications.map(item=>platformName(item.platform)).join('、')||'尚未发布')}</section><section class="studio-inspector-section"><header><b>最近动态</b><span>${projectEvents.length} 条</span></header><div class="studio-project-events">${eventMarkup}</div></section>`;
